"""Text-to-SQL harness: draft -> execute -> (repair once) -> answer.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}      (hint is BIRD's evidence; "" for Spider)
  env.chat(messages, max_tokens=None) -> str     policy call (capped per task: env.max_calls)
  env.schema(db_id) -> str                       CREATE statements of the database
  env.execute(sql, max_rows=20) -> dict          read-only run: {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str                 column descriptions if the dataset ships them, else ""
  env.prompt(name) -> str                        text of a file in this harness
  env.config -> dict                             parsed config.json
"""

import json
import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    t = (text or "").strip()
    m = re.search(r"(?is)\b(select|with)\b.*", t)
    if m:
        return m.group(0).rstrip(";").strip()
    return t.rstrip(";").strip()


def _run(env, sql):
    try:
        return env.execute(sql, max_rows=20)
    except Exception as exc:  # harness-side failure must not kill the task
        return {"ok": False, "columns": [], "rows": [], "n_rows": 0, "error": str(exc)}


def _feedback(res):
    if not res.get("ok"):
        return "Execution ERROR: %s" % (res.get("error") or "unknown error")
    rows = res.get("rows") or []
    cols = res.get("columns") or []
    if not rows:
        return ("Executed successfully but returned ZERO rows (columns: %s)."
                % json.dumps(cols))
    return ("Returned %s row(s); columns: %s; first rows: %s"
            % (res.get("n_rows", len(rows)), json.dumps(cols),
               json.dumps(rows[:5], default=str)))


REPAIR_RULES = """Your previous query did not produce a usable answer. Diagnose and fix it, then output ONE corrected SQLite query in a single ```sql block.

Checklist for an empty result (most common cause is an over-strict filter, not missing data):
- Text matching: stored values may differ in case, spacing, punctuation or wording from the question. Prefer case-insensitive substring matching, e.g. lower(col) LIKE lower('%term%'), instead of exact '=' when the question quotes a phrase loosely. Trim stray spaces inside the quoted term.
- Literal values: confirm the exact spelling/format actually stored (codes vs names, 'T'/'F' vs 1/0, date formats, numeric units). If unsure, inspect distinct values with a small probe query instead of guessing again.
- Joins: verify the foreign-key direction and the key columns against the schema; a reversed or wrong-column join silently yields nothing. Consider whether an inner join should be a LEFT JOIN / EXISTS.
- Filters combined with AND may each be individually fine but jointly impossible; relax the least essential condition.
For an execution error: fix the syntax, unknown column/table names (use the schema verbatim), or aggregate/GROUP BY misuse.

Keep the answer shape aligned with the question: do not add or drop requested columns while repairing, and keep DISTINCT / ORDER BY / LIMIT only when the question asks for them. An empty result is acceptable ONLY after you have verified the filters and joins are right."""


PROJECTION_RULES = """The query ran, but the set of columns it returns may not match what the question asks for. Re-read the question and decide the projection explicitly, then output ONE final SQLite query in a single ```sql block (repeat the same query unchanged if the projection is already right).

- If a noun in the question corresponds to an actual column name in the schema (e.g. "details" -> Other_Details / Details, "description" -> Description, "text" -> ..._Text, "name", "number", "code", "date"), return ONLY that column, not the whole row. A column that is mostly NULL is still the right answer if the question names it.
- If the question names several attributes, return exactly those, in the order asked.
- If the question asks about whole entities and needs TWO OR MORE tables joined, and names no specific attributes, keep the columns of EVERY joined table (SELECT T1.*, T2.* ...), not just the first table's.
- If the question asks about whole entities of a SINGLE table and no column matches its nouns, SELECT that table's columns (T1.*).
- Never add columns the question did not ask for; keep filters, joins, DISTINCT, ORDER BY and LIMIT exactly as needed by the question."""


CREATE_RE = re.compile(
    r"CREATE\s+(?:TEMP\s+|TEMPORARY\s+)?(?:TABLE|VIEW)\s+(?:IF\s+NOT\s+EXISTS\s+)?"
    r"[`\"\[]?([A-Za-z_][\w$]*)[`\"\]]?\s*\((.*)", re.S | re.I)


def _split_top(body):
    parts, depth, cur, quote = [], 0, [], None
    for ch in body:
        if quote:
            cur.append(ch)
            if ch == quote:
                quote = None
            continue
        if ch in "'\"`":
            quote = ch
            cur.append(ch)
        elif ch == "(":
            depth += 1
            cur.append(ch)
        elif ch == ")":
            if depth == 0:
                break
            depth -= 1
            cur.append(ch)
        elif ch == "," and depth == 0:
            parts.append("".join(cur))
            cur = []
        else:
            cur.append(ch)
    parts.append("".join(cur))
    return parts


SKIP_CONSTRAINT = re.compile(
    r"^(primary|unique|foreign|check|constraint|key|index)\b", re.I)


def _table_columns(schema):
    """Map table name -> list of column names, parsed from CREATE statements."""
    out = {}
    for m in CREATE_RE.finditer(schema or ""):
        name = m.group(1)
        cols = []
        for part in _split_top(m.group(2)):
            p = part.strip()
            if not p or SKIP_CONSTRAINT.match(p):
                continue
            cm = re.match(r"[`\"\[]?([A-Za-z_][\w$]*)[`\"\]]?", p)
            if cm:
                cols.append(cm.group(1))
        if cols:
            out[name.lower()] = cols
    return out


def _referenced_tables(sql, table_cols):
    refs = re.findall(r"(?is)\b(?:from|join)\s+[`\"\[]?([A-Za-z_][\w$]*)", sql or "")
    seen, out = set(), []
    for r in refs:
        k = r.lower()
        if k in table_cols and k not in seen:
            seen.add(k)
            out.append(k)
    return out


def _projection_issue(sql, res, question, table_cols):
    """Cheap, generic check that the returned column set fits the question."""
    if not res.get("ok"):
        return False
    cols = res.get("columns") or []
    if not cols:
        return False
    low = (sql or "").lower()
    if re.search(r"\b(group\s+by|count\s*\(|sum\s*\(|avg\s*\(|min\s*\(|max\s*\()\b", low):
        return False
    refs = _referenced_tables(sql, table_cols)
    star = bool(re.search(r"(?is)select\s+(distinct\s+)?[\w`\"\.\[\]]*\.\*", sql or "")) \
        or bool(re.search(r"(?is)select\s+(distinct\s+)?\*", sql or ""))
    # Joined several tables but projected only one table's worth of columns.
    if len(refs) >= 2 and star:
        total = sum(len(table_cols[t]) for t in refs)
        if len(cols) < total:
            return True
    # Returned a whole row although the question names an attribute-like column.
    if star and len(refs) == 1:
        q = (question or "").lower()
        for c in table_cols[refs[0]]:
            cl = c.lower().replace("_", " ")
            if len(cl) >= 4 and cl in q:
                return True
    return False


def solve(task, env):
    cfg = env.config or {}
    max_tokens = cfg.get("max_tokens", 1200)
    schema = env.schema(task["db_id"])
    user = "Database: %s\n\nSchema:\n%s\n\nQuestion: %s" % (
        task["db_id"], schema, task["question"])
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += "\n\nColumn descriptions:\n" + desc.strip()
    if task.get("hint"):
        user += "\nHint: %s" % task["hint"]

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)
    if not sql:
        return {"sql": sql}

    res = _run(env, sql)
    broken = (not res.get("ok")) or not (res.get("rows") or [])
    width_issue = False
    table_cols = {}
    if not broken:
        try:
            table_cols = _table_columns(schema)
            width_issue = _projection_issue(sql, res, task.get("question"), table_cols)
        except Exception:
            width_issue = False
    if not broken and not width_issue:
        return {"sql": sql}

    if broken:
        followup = (
            "Draft query:\n```sql\n%s\n```\n\nResult of running it: %s\n\n%s"
            % (sql, _feedback(res), REPAIR_RULES)
        )
    else:
        listing = "\n".join(
            "- %s: %s" % (t, ", ".join(table_cols[t]))
            for t in _referenced_tables(sql, table_cols))
        followup = (
            "Draft query:\n```sql\n%s\n```\n\nResult of running it: %s\n\n"
            "Full column lists of the tables your query uses:\n%s\n\n%s"
            % (sql, _feedback(res), listing, PROJECTION_RULES)
        )
    messages = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": followup},
    ]
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}

    res2 = _run(env, sql2)
    if not res2.get("ok"):
        return {"sql": sql}
    if broken:
        # Prefer a query that actually returns data; never swap in a broken one.
        if (res2.get("rows") or []) or not res.get("ok"):
            return {"sql": sql2}
        return {"sql": sql}
    # Projection-only revision: accept it when it still produces data.
    if res2.get("rows") or []:
        return {"sql": sql2}
    return {"sql": sql}

